Generate a standalone C reproducer that triggers this vulnerability:

File: apps/list.c
Line: 771
Function: collect_signatures
Bug type: null-pointer-dereference
CWE: CWE-476
Explanation: sk_EVP_SIGNATURE_new() in list_signatures() (line 778) is not checked for NULL. If it returns NULL, the NULL stack is passed into EVP_SIGNATURE_do_all_provided() and then to collect_signatures(), where sk_EVP_SIGNATURE_push(sig_stack, sig) dereferences the NULL pointer.

Source context:
```c
      731:         STACK_OF(OPENSSL_CSTRING) *names = NULL;
      732: 
      733:         if (select_name != NULL && !EVP_SKEYMGMT_is_a(k, select_name))
      734:             continue;
      735: 
      736:         names = sk_OPENSSL_CSTRING_new(name_cmp);
      737:         if (names != NULL && EVP_SKEYMGMT_names_do_all(k, collect_names, names)) {
      738:             const char *desc = EVP_SKEYMGMT_get0_description(k);
      739: 
      740:             BIO_printf(bio_out, "  Name: ");
      741:             if (desc != NULL)
      742:                 BIO_printf(bio_out, "%s", desc);
      743:             else
      744:                 BIO_printf(bio_out, "%s", sk_OPENSSL_CSTRING_value(names, 0));
      745:             BIO_printf(bio_out, "\n");
      746:             BIO_printf(bio_out, "    Type: Provider Algorithm\n");
      747:             BIO_printf(bio_out, "    IDs: ");
      748:             print_names(bio_out, names);
      749:             BIO_printf(bio_out, " @ %s\n",
      750:                 OSSL_PROVIDER_get0_name(EVP_SKEYMGMT_get0_provider(k)));
      751:         }
      752:         sk_OPENSSL_CSTRING_free(names);
      753:     }
      754:     sk_EVP_SKEYMGMT_pop_free(km_stack, EVP_SKEYMGMT_free);
      755: }
      756: 
      757: DEFINE_STACK_OF(EVP_SIGNATURE)
      758: static int signature_cmp(const EVP_SIGNATURE *const *a,
      759:     const EVP_SIGNATURE *const *b)
      760: {
      761:     return strcmp(OSSL_PROVIDER_get0_name(EVP_SIGNATURE_get0_provider(*a)),
      762:         OSSL_PROVIDER_get0_name(EVP_SIGNATURE_get0_provider(*b)));
      763: }
