      768: 
      769:     if (is_signature_fetchable(sig)
      770:         && EVP_SIGNATURE_up_ref(sig)
>>>   771:         && sk_EVP_SIGNATURE_push(sig_stack, sig) <= 0)
      772:         EVP_SIGNATURE_free(sig); /* up-ref successful but push to stack failed */
      773: }
      774: 
      775: static void list_signatures(void)
      776: {
      777:     int i, count = 0;
      778:     STACK_OF(EVP_SIGNATURE) *sig_stack = sk_EVP_SIGNATURE_new(signature_cmp);
      779: 
      780:     EVP_SIGNATURE_do_all_provided(app_get0_libctx(), collect_signatures,
      781:         sig_stack);
      782:     sk_EVP_SIGNATURE_sort(sig_stack);
      783: 
      784:     for (i = 0; i < sk_EVP_SIGNATURE_num(sig_stack); i++) {
      785:         EVP_SIGNATURE *k = sk_EVP_SIGNATURE_value(sig_stack, i);
      786:         STACK_OF(OPENSSL_CSTRING) *names = NULL;
      787: 
      788:         if (select_name != NULL && !EVP_SIGNATURE_is_a(k, select_name))
      789:             continue;
