      791:         names = sk_OPENSSL_CSTRING_new(name_cmp);
      792:         if (names != NULL && EVP_SIGNATURE_names_do_all(k, collect_names, names)) {
      793:             count++;
      794:             BIO_printf(bio_out, "  ");
      795:             print_names(bio_out, names);
      796: 
      797:             BIO_printf(bio_out, " @ %s\n",
      798:                 OSSL_PROVIDER_get0_name(EVP_SIGNATURE_get0_provider(k)));
      799: 
      800:             if (verbose) {
      801:                 const char *desc = EVP_SIGNATURE_get0_description(k);
      802: 
      803:                 if (desc != NULL)
      804:                     BIO_printf(bio_out, "    description: %s\n", desc);
      805:                 print_param_types("settable operation parameters",
      806:                     EVP_SIGNATURE_settable_ctx_params(k), 4);
      807:                 print_param_types("retrievable operation parameters",
      808:                     EVP_SIGNATURE_gettable_ctx_params(k), 4);
      809:             }
      810:         }
